using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class DockDeckUVAlignment{const string D="Assets/Scenes/Oasis/YachtPortAtlas";static DockDeckUVAlignment(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("DockDeckUVAlignment.request"))return;File.Delete("DockDeckUVAlignment.request");try{int changed=0;for(int index=1;index<=6;index++){var prefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/SouthBeach/Docking Pier "+index+".prefab");foreach(var filter in prefab.GetComponentsInChildren<MeshFilter>()){if(!filter.name.Contains("deck and foundation"))continue;var mesh=filter.sharedMesh;var points=mesh.vertices;var normals=mesh.normals;var uv=mesh.uv;var flags=new List<Vector4>();mesh.GetUVs(1,flags);for(int i=0;i<points.Length;i++)if(flags[i].x==0&&Mathf.Abs(normals[i].y)>.65f){var local=prefab.transform.InverseTransformPoint(filter.transform.TransformPoint(points[i]));uv[i]=new Vector2(local.x*.5f,local.z*.5f);changed++;}mesh.uv=uv;EditorUtility.SetDirty(mesh);}PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var pier=scene.GetRootGameObjects().Single(g=>g.name=="South Beach Bays and Docking Piers").transform.GetChild(2);var target=pier.TransformPoint(new Vector3(0,.3f,32));typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,target+Vector3.up*13,target,"Aligned-Dock-Deck-Planks"});File.WriteAllText("FinalEnvironmentRoadReview/DockDeckUVAlignmentReport.txt","SUCCESS corrected deck UV vertices="+changed+" across six pier prefab meshes; plank grain follows local pier width, boards across deck; geometry, atlas material, side/post UVs retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/DockDeckUVAlignmentReport.txt","FAILED "+e);Debug.LogException(e);}}}
